"""Correct only a derived alias count after native rows were excluded from parent comparisons."""
import copy,hashlib,json
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
rd=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();put=lambda p,o:p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
b=rd(R/'economic_alias_correction_binding.json');assert b['bound_before_readonly_execution'] and sha(Path(__file__))==b['source_sha256']
for path,h in b['immutable_financial_inputs_sha256'].items():assert sha(ROOT/path)==h
p=R/'joint_economic_review.json';assert sha(p)==b['initial_derived_report_sha256'];before=rd(p);report=rd(R/'report.json');parents={c['fingerprint'] for c in report['configs'].values() if c['scope']=='parent'};natives={c['fingerprint'] for c in report['configs'].values() if c['scope']=='native'};rows=before['comparison_rows'];assert len(parents)==len(natives)==6 and len(rows)==18 and {z['fingerprint'] for z in rows}==parents
for fp in parents:assert sorted(z['cost'] for z in rows if z['fingerprint']==fp)==[1,2,3]
expected=sum(all(z['full_NAV_hash_identical'] for z in rows if z['fingerprint']==fp) for fp in parents);assert before['allcost_path_alias_new_graphs']==6+expected and not any(z['full_NAV_hash_identical'] for z in rows) and expected==0
assert before['strict_four_metric_improvement_rows']==sum(z['strict_four_metric_improvement'] for z in rows) and before['old_weakly_dominated_rows']==sum(z['old_weakly_dominates'] for z in rows)
original=R/'joint_economic_review_initial.json';assert not original.exists();original.write_bytes(p.read_bytes());after=copy.deepcopy(before);after['allcost_path_alias_new_graphs']=expected;after['alias_count_correction']={'reason':'Initial sum iterated all12 new configs after comparisons were restricted to6parent configs; all(empty) counted6native configs as aliases. Count now requires exactly three saved parent comparison rows per parent.','initial_report':str(original.relative_to(ROOT)),'initial_report_sha256':sha(original),'only_derived_aggregate_corrected':True,'financial_reports_archives_specs_and_all_comparison_rows_unchanged':True,'source':'correct_economic_alias_summary.py'};check=copy.deepcopy(after);check.pop('alias_count_correction');check['allcost_path_alias_new_graphs']=before['allcost_path_alias_new_graphs'];assert check==before;put(p,after)
for path,h in b['immutable_financial_inputs_sha256'].items():assert sha(ROOT/path)==h
put(R/'economic_alias_correction_verification.json',{'passed':True,'recorded_utc':datetime.now(timezone.utc).isoformat(),'source_sha256':b['source_sha256'],'original_source_and_initial_output_retained':True,'original_aggregate_count':6,'corrected_parent_only_aggregate_count':0,'all18_parent_comparison_rows_unchanged':True,'all_other_metrics_mechanism_rows_and_statuses_unchanged':True,'initial_output_sha256':sha(original),'corrected_output_sha256':sha(p),'new_strategy_account_or_cashflow_evaluations':0,'immutable_financial_inputs_sha256':b['immutable_financial_inputs_sha256']});print(json.dumps({'passed':True,'initial_derived_alias_count':6,'corrected_parent_only_alias_count':0,'comparison_rows':18,'new_evaluations':0}))
